-- Campaign isolation; retain settings id=1 and existing campaign data.
alter table public.settings drop constraint settings_id_check;
alter table public.settings alter column id add generated by default as identity (start with 2);
alter table public.settings add column slug text not null default 'mac-dinh' unique check(slug ~ '^[a-z0-9][a-z0-9-]{0,78}[a-z0-9]$'),
 add column starts_at timestamptz, add column ends_at timestamptz,
 add column max_plays_per_phone integer default 1 check(max_plays_per_phone between 1 and 10000),
 add column play_period text not null default 'campaign' check(play_period in ('campaign','daily')),
 add column max_wins_per_phone integer check(max_wins_per_phone between 1 and 10000),
 add column max_total_plays integer check(max_total_plays between 1 and 100000000),
 add constraint campaign_dates check(starts_at is null or ends_at is null or starts_at<ends_at);
alter table public.settings alter column slug drop default;
grant usage,select on sequence public.settings_id_seq to service_role;
alter table public.prizes add column campaign_id integer not null default 1 references public.settings(id), add unique(campaign_id,id);
alter table public.vouchers add column campaign_id integer not null default 1 references public.settings(id), add unique(campaign_id,id,prize_id), add foreign key(campaign_id,prize_id) references public.prizes(campaign_id,id);
alter table public.plays add column campaign_id integer not null default 1 references public.settings(id), add foreign key(campaign_id,prize_id) references public.prizes(campaign_id,id), add foreign key(campaign_id,voucher_id,prize_id) references public.vouchers(campaign_id,id,prize_id);
alter table public.plays drop constraint plays_phone_key;
alter table public.vouchers drop constraint vouchers_code_key, add unique(campaign_id,code);
create index plays_campaign_phone_created on public.plays(campaign_id,phone,created_at);
create index plays_campaign_id on public.plays(campaign_id,id desc);
create index vouchers_campaign_available on public.vouchers(campaign_id,prize_id) where not used;
create function public.campaign_is_open(cfg public.settings,ts timestamptz) returns boolean language sql stable security invoker set search_path='' as $$
 select cfg.active and (cfg.starts_at is null or cfg.starts_at<=ts) and (cfg.ends_at is null or cfg.ends_at>ts)
$$;
create function public.campaign_weights(p_campaign integer) returns table(prize_id uuid,prize_name text,effective_quantity bigint,tickets numeric) language sql stable security invoker set search_path='' as $$
 with cfg as (select planned_plays,no_win_weight from public.settings where id=p_campaign),
 counts as (select count(*)::numeric n from public.plays where campaign_id=p_campaign),
 stock as (
 select p.id,p.name,p.unlimited,p.fallback_weight,
 case when p.unlimited then null::bigint when p.requires_code then least(p.quantity::bigint,coalesce(v.available,0)) else p.quantity::bigint end as effective
 from public.prizes p left join (select prize_id,count(*) available from public.vouchers where not used group by prize_id) v on v.prize_id=p.id where p.campaign_id=p_campaign
 ),
 totals as (select coalesce(sum(effective),0)::numeric finite_stock,coalesce(sum(fallback_weight) filter(where unlimited),0)::numeric unlimited_weight from stock),
 base as (select greatest(1::numeric,cfg.planned_plays-counts.n,totals.finite_stock) denominator,totals.finite_stock,totals.unlimited_weight+cfg.no_win_weight weight_sum,cfg.no_win_weight from cfg cross join counts cross join totals)
 select s.id,s.name,s.effective,case when s.unlimited then (b.denominator-b.finite_stock)*s.fallback_weight else s.effective*b.weight_sum end from stock s cross join base b
 union all select null::uuid,'Chúc may mắn',null::bigint,(denominator-finite_stock)*no_win_weight from base
$$;
create function public.campaign_odds(p_campaign integer) returns table(prize_id uuid,prize_name text,effective_quantity bigint,probability numeric) language sql stable security invoker set search_path='' as $$
 with weights as (select * from public.campaign_weights(p_campaign)),
 rounded as (select w.*,trunc(100::numeric*w.tickets/sum(w.tickets) over(),12) chance,row_number() over(order by (w.tickets>0) desc,w.prize_id nulls first) recipient from weights w)
 select prize_id,prize_name,effective_quantity,chance+case when recipient=1 then 100::numeric-sum(chance) over() else 0 end from rounded
$$;

create function public.campaign_draw(p_campaign integer,p_name text,p_phone text,p_request uuid) returns jsonb language plpgsql security invoker set search_path='' as $$
declare cfg public.settings%rowtype; existing public.plays%rowtype; p public.prizes%rowtype; v public.vouchers%rowtype; odds jsonb; candidate record; total_tickets numeric; cutoff numeric; raw numeric; r numeric; cumulative numeric:=0; chosen uuid; reward text:='Chúc may mắn'; saved public.plays%rowtype; remaining integer; used_count bigint; won_count bigint; win_capped boolean; ts timestamptz; day_start timestamptz;
begin
 if p_name is null or length(trim(p_name)) not between 2 and 100 or p_phone is null or p_phone !~ '^0[35789][0-9]{8}$' or p_request is null then raise exception 'INVALID_INPUT'; end if;
 select * into cfg from public.settings where id=p_campaign for update;
 if not found then raise exception 'CAMPAIGN_NOT_FOUND'; end if;
 ts:=clock_timestamp();
 day_start:=date_trunc('day',ts at time zone 'Asia/Ho_Chi_Minh') at time zone 'Asia/Ho_Chi_Minh';
 select * into existing from public.plays where request_id=p_request;
 if found then
 if existing.campaign_id<>p_campaign or existing.phone<>p_phone or existing.name<>trim(p_name) then raise exception 'INVALID_REQUEST'; end if;
 select count(*) into used_count from public.plays where campaign_id=p_campaign and phone=p_phone and (cfg.play_period='campaign' or created_at>=day_start);
 remaining:=case when cfg.max_plays_per_phone is null then null else greatest(0,cfg.max_plays_per_phone-used_count)::integer end;
 return to_jsonb(existing)||jsonb_build_object('remaining_plays',remaining,'can_continue',public.campaign_is_open(cfg,ts)); end if;
 if not public.campaign_is_open(cfg,ts) then raise exception 'GAME_CLOSED'; end if;
 select count(*) into used_count from public.plays where campaign_id=p_campaign and phone=p_phone and (cfg.play_period='campaign' or created_at>=day_start);
 if cfg.max_plays_per_phone is not null and used_count>=cfg.max_plays_per_phone then raise exception 'PLAY_LIMIT'; end if;
 if cfg.max_total_plays is not null and (select count(*) from public.plays where campaign_id=p_campaign)>=cfg.max_total_plays then raise exception 'CAMPAIGN_LIMIT'; end if;
 select count(*) into won_count from public.plays where campaign_id=p_campaign and phone=p_phone and prize_id is not null;
 win_capped:=cfg.max_wins_per_phone is not null and won_count>=cfg.max_wins_per_phone;
 select jsonb_agg(to_jsonb(w)||jsonb_build_object('probability',o.probability) order by w.prize_id nulls last),sum(w.tickets)
 into odds,total_tickets from public.campaign_weights(p_campaign) w join public.campaign_odds(p_campaign) o on w.prize_id is not distinct from o.prize_id;
 if win_capped then
 odds:=jsonb_build_array(jsonb_build_object('prize_id',null,'prize_name','Chúc may mắn','effective_quantity',null,'tickets',1,'probability',100,'reason','WIN_LIMIT')); total_tickets:=1;
 end if;
 if total_tickets is null or total_tickets<=0 or total_tickets>79228162514264337593543950336::numeric then raise exception 'INVALID_ODDS'; end if;
 cutoff:=79228162514264337593543950336::numeric-mod(79228162514264337593543950336::numeric,total_tickets);
 -- 96 independent random bits; rejection sampling removes modulo bias.
 loop
 raw:=('x'||substr(replace(gen_random_uuid()::text,'-',''),1,12))::bit(48)::bigint::numeric*281474976710656::numeric+('x'||substr(replace(gen_random_uuid()::text,'-',''),1,12))::bit(48)::bigint::numeric;
 exit when raw<cutoff;
 end loop;
 r:=mod(raw,total_tickets);
 for candidate in select * from jsonb_to_recordset(odds) as o(prize_id uuid,prize_name text,tickets numeric) order by prize_id nulls last loop
 cumulative:=cumulative+candidate.tickets;
 if r<cumulative then chosen:=candidate.prize_id; exit; end if;
 end loop;
 if chosen is not null then
 select * into strict p from public.prizes where id=chosen and campaign_id=p_campaign for update;
 if not p.unlimited and p.quantity<=0 then raise exception 'STOCK_CONFLICT'; end if;
 if p.requires_code then
 select * into v from public.vouchers where campaign_id=p_campaign and prize_id=p.id and not used order by id limit 1 for update;
 if v.id is null then raise exception 'STOCK_CONFLICT'; end if;
 update public.vouchers set used=true where id=v.id;
 end if;
 if not p.unlimited then update public.prizes set quantity=quantity-1 where id=p.id; end if;
 reward:=p.name;
 end if;
 insert into public.plays(campaign_id,request_id,name,phone,prize_id,prize_name,voucher_id,voucher_code,odds_snapshot,created_at) values(p_campaign,p_request,trim(p_name),p_phone,chosen,reward,v.id,v.code,odds,ts) returning * into saved;
 remaining:=case when cfg.max_plays_per_phone is null then null else greatest(0,cfg.max_plays_per_phone-used_count-1)::integer end;
 return to_jsonb(saved)||jsonb_build_object('remaining_plays',remaining,'can_continue',public.campaign_is_open(cfg,ts) and (cfg.max_total_plays is null or (select count(*) from public.plays where campaign_id=p_campaign)<cfg.max_total_plays));
end $$;

create function public.campaign_create(p_slug text,p_title text) returns integer language plpgsql security invoker set search_path='' as $$
declare result integer;
begin
 if p_slug is null or p_slug !~ '^[a-z0-9][a-z0-9-]{0,78}[a-z0-9]$' or p_title is null or length(trim(p_title)) not between 1 and 120 then raise exception 'INVALID_SETTINGS'; end if;
 insert into public.settings(slug,title,active) values(p_slug,trim(p_title),false) returning id into result;
 return result;
end $$;
create function public.campaign_save(p_campaign integer,p_revision bigint,p_title text,p_description text,p_active boolean,p_planned integer,p_no_win integer,p_starts timestamptz,p_ends timestamptz,p_max_plays integer,p_period text,p_max_wins integer,p_max_total integer) returns void language plpgsql security invoker set search_path='' as $$
declare cfg public.settings%rowtype;
begin
 select * into cfg from public.settings where id=p_campaign for update;
 if not found then raise exception 'CAMPAIGN_NOT_FOUND'; end if;
 if cfg.revision is distinct from p_revision then raise exception 'STALE_CONFIG'; end if;
 if p_title is null or length(trim(p_title)) not between 1 and 120 or p_description is null or length(p_description)>500 or p_active is null or p_planned is null or p_planned not between 1 and 1000000 or p_no_win is null or p_no_win not between 1 and 1000000 or p_period is null or p_period not in ('campaign','daily') or (p_starts is not null and p_ends is not null and p_starts>=p_ends) or (p_max_plays is not null and p_max_plays not between 1 and 10000) or (p_max_wins is not null and p_max_wins not between 1 and 10000) or (p_max_total is not null and p_max_total not between 1 and 100000000) then raise exception 'INVALID_SETTINGS'; end if;
 if cfg.active and p_active and row(cfg.planned_plays,cfg.no_win_weight,cfg.starts_at,cfg.ends_at,cfg.max_plays_per_phone,cfg.play_period,cfg.max_wins_per_phone,cfg.max_total_plays) is distinct from row(p_planned,p_no_win,p_starts,p_ends,p_max_plays,p_period,p_max_wins,p_max_total) then raise exception 'PAUSE_CAMPAIGN'; end if;
 update public.settings set title=trim(p_title),description=p_description,active=p_active,planned_plays=p_planned,no_win_weight=p_no_win,starts_at=p_starts,ends_at=p_ends,max_plays_per_phone=p_max_plays,play_period=p_period,max_wins_per_phone=p_max_wins,max_total_plays=p_max_total where id=p_campaign;
 if p_active and not cfg.active and not exists(select 1 from public.campaign_odds(p_campaign) o where o.prize_id is not null and o.probability>0) then raise exception 'NO_AVAILABLE_PRIZE'; end if;
end $$;
create function public.campaign_save_prize(p_campaign integer,p_id uuid,p_revision bigint,p_name text,p_quantity integer,p_unlimited boolean,p_requires_code boolean,p_weight integer) returns uuid language plpgsql security invoker set search_path='' as $$
declare cfg public.settings%rowtype; result uuid; current_revision bigint;
begin
 select * into cfg from public.settings where id=p_campaign for update;
 if not found then raise exception 'CAMPAIGN_NOT_FOUND'; end if;
 if cfg.active then raise exception 'PAUSE_CAMPAIGN'; end if;
 if p_name is null or length(trim(p_name)) not between 1 and 80 or p_quantity is null or p_quantity<0 or p_unlimited is null or p_requires_code is null or p_weight is null or p_weight not between 0 and 1000000 or (p_unlimited and (p_quantity<>0 or p_requires_code)) then raise exception 'INVALID_PRIZE'; end if;
 if p_id is null then insert into public.prizes(campaign_id,name,quantity,probability,requires_code,unlimited,fallback_weight) values(p_campaign,trim(p_name),p_quantity,0,p_requires_code,p_unlimited,p_weight) returning id into result;
 else
 select revision into current_revision from public.prizes where id=p_id and campaign_id=p_campaign for update;
 if not found then raise exception 'PRIZE_NOT_FOUND'; end if;
 if current_revision is distinct from p_revision then raise exception 'STALE_CONFIG'; end if;
 if (p_unlimited or not p_requires_code) and exists(select 1 from public.vouchers where campaign_id=p_campaign and prize_id=p_id and not used) then raise exception 'EXISTING_VOUCHERS'; end if;
 update public.prizes set name=trim(p_name),quantity=p_quantity,probability=0,requires_code=p_requires_code,unlimited=p_unlimited,fallback_weight=p_weight where id=p_id and campaign_id=p_campaign returning id into result;
 end if;
 return result;
end $$;
create function public.campaign_import(p_campaign integer,p_prize uuid,p_codes text[]) returns integer language plpgsql security invoker set search_path='' as $$
declare cfg public.settings%rowtype; inserted integer;
begin
 select * into cfg from public.settings where id=p_campaign for update;
 if not found then raise exception 'CAMPAIGN_NOT_FOUND'; end if;
 if cfg.active then raise exception 'PAUSE_CAMPAIGN'; end if;
 if not exists(select 1 from public.prizes where campaign_id=p_campaign and id=p_prize and requires_code and not unlimited) then raise exception 'INVALID_VOUCHER_PRIZE'; end if;
 if p_codes is null or cardinality(p_codes) not between 1 and 5000 or exists(select 1 from unnest(p_codes) c where c is null or length(trim(c)) not between 1 and 200) then raise exception 'INVALID_CODES'; end if;
 insert into public.vouchers(campaign_id,prize_id,code) select p_campaign,p_prize,trim(c) from unnest(p_codes) c group by trim(c) on conflict(campaign_id,code) do nothing;
 get diagnostics inserted=row_count;return inserted;
end $$;
-- Keep the previous app compatible with the legacy campaign during deployment.
create or replace function public.draw_weights() returns table(prize_id uuid,prize_name text,effective_quantity bigint,tickets numeric) language sql stable security invoker set search_path='' as $$ select * from public.campaign_weights(1) $$;
create or replace function public.draw_odds() returns table(prize_id uuid,prize_name text,effective_quantity bigint,probability numeric) language sql stable security invoker set search_path='' as $$ select * from public.campaign_odds(1) $$;
create or replace function public.draw(p_name text,p_phone text,p_request uuid) returns jsonb language sql security invoker set search_path='' as $$ select public.campaign_draw(1,p_name,p_phone,p_request) $$;
create or replace function public.import_vouchers(p_prize uuid,p_codes text[]) returns integer language sql security invoker set search_path='' as $$ select public.campaign_import(1,p_prize,p_codes) $$;
create or replace function public.save_prize_versioned(p_id uuid,p_name text,p_quantity integer,p_unlimited boolean,p_requires_code boolean,p_fallback_weight integer,p_expected_revision bigint) returns uuid language sql security invoker set search_path='' as $$ select public.campaign_save_prize(1,p_id,p_expected_revision,p_name,p_quantity,p_unlimited,p_requires_code,p_fallback_weight) $$;
create or replace function public.save_campaign_versioned(p_title text,p_description text,p_active boolean,p_planned_plays integer,p_no_win_weight integer,p_expected_revision bigint) returns void language sql security invoker set search_path='' as $$ select public.campaign_save(1,p_expected_revision,p_title,p_description,p_active,p_planned_plays,p_no_win_weight,null,null,1,'campaign',null,null) $$;
revoke execute on function public.campaign_is_open(public.settings,timestamptz),public.campaign_weights(integer),public.campaign_odds(integer),public.campaign_draw(integer,text,text,uuid),public.campaign_create(text,text),public.campaign_save(integer,bigint,text,text,boolean,integer,integer,timestamptz,timestamptz,integer,text,integer,integer),public.campaign_save_prize(integer,uuid,bigint,text,integer,boolean,boolean,integer),public.campaign_import(integer,uuid,text[]) from public,anon,authenticated;
grant execute on function public.campaign_is_open(public.settings,timestamptz),public.campaign_weights(integer),public.campaign_odds(integer),public.campaign_draw(integer,text,text,uuid),public.campaign_create(text,text),public.campaign_save(integer,bigint,text,text,boolean,integer,integer,timestamptz,timestamptz,integer,text,integer,integer),public.campaign_save_prize(integer,uuid,bigint,text,integer,boolean,boolean,integer),public.campaign_import(integer,uuid,text[]) to service_role;
